findings.fix:
Introduce a user‑defined type guard that narrows the unknown value to a shape with the required properties, e.g.
```ts
function isAccountShape(v: unknown): v is { id: unknown; name: unknown } {
  return typeof v === "object" && v !== null && !Array.isArray(v) &&
    "id" in v && "name" in v;
}

function parseAccount(value: unknown): Account {
  if (!isAccountShape(value)) throw new Error("Invalid account");
  if (typeof value.id !== "number" || !Number.isSafeInteger(value.id) || value.id <= 0) throw new Error("Invalid account");
  if (typeof value.name !== "string") throw new Error("Invalid account");
  return { id: value.id, name: value.name };
}
```
